import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.mRCPFc5l.js";const o=JSON.parse('{"title":"WITH 查询为什么返回空数据：重新定义 SQL 批处理结果","description":"从遗留 PHP 报表适配 CTE 的改动出发，说明按首个关键字分类的缺陷、多结果集遍历，以及空结果与失败的区分。","frontmatter":{"title":"WITH 查询为什么返回空数据：重新定义 SQL 批处理结果","description":"从遗留 PHP 报表适配 CTE 的改动出发，说明按首个关键字分类的缺陷、多结果集遍历，以及空结果与失败的区分。"},"headers":[],"relativePath":"practice/sql-batch-result-contract.md","filePath":"practice/sql-batch-result-contract.md","lastUpdated":1792725069000}'),e={name:"practice/sql-batch-result-contract.md"};function l(p,s,h,r,k,d){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="with-查询为什么返回空数据-重新定义-sql-批处理结果" tabindex="-1">WITH 查询为什么返回空数据：重新定义 SQL 批处理结果 <a class="header-anchor" href="#with-查询为什么返回空数据-重新定义-sql-批处理结果" aria-label="Permalink to &quot;WITH 查询为什么返回空数据：重新定义 SQL 批处理结果&quot;">​</a></h1><p>同一段 SQL 在数据库工具里有结果，放进报表系统却返回空数组。问题不一定在 SQL；也可能是数据库封装先看了第一个关键字，把它分到了不读取结果的路径。</p><p>本文依据一个遗留 PHP 报表服务和配套 PC 页面近期改动整理，核对日期为 <strong>2026-10-23</strong>。只做本地源码分析，没有连接数据库或执行任何 SQL。下面示例使用合成内容，验证项均指隔离测试环境。</p><h2 id="不是-select-开头-不等于-不返回表格" tabindex="-1">“不是 SELECT 开头”不等于“不返回表格” <a class="header-anchor" href="#不是-select-开头-不等于-不返回表格" aria-label="Permalink to &quot;“不是 SELECT 开头”不等于“不返回表格”&quot;">​</a></h2><p>旧封装根据首个关键字区分读写。它遇到 <code>WITH</code>、声明语句、前置注释或多语句批处理时，可能执行了 SQL，却没有按结果集读取。</p><p>这个最小示例就足以说明问题：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WITH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> sample</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> value</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> sample</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>为首词判断再加一个 <code>WITH</code> 分支，只能解决一种形式。近期修复增加了专门的批处理执行路径，不依赖首词决定是否取数，而是交由驱动结果描述来判断。</p><h2 id="批处理的第一个结果不一定有列" tabindex="-1">批处理的第一个结果不一定有列 <a class="header-anchor" href="#批处理的第一个结果不一定有列" aria-label="Permalink to &quot;批处理的第一个结果不一定有列&quot;">​</a></h2><p>一次执行可能先返回受影响行数，然后才返回带列的表格。近期实现约定：跳过无列结果，返回遇到的第一个有列结果集。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行批处理</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>当前结果有列？ ── 是 → 读取行并返回</span></span>
<span class="line"><span>   │ 否</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>激活下一个结果</span></span>
<span class="line"><span>   ├─ 还有结果 → 继续检查</span></span>
<span class="line"><span>   ├─ 已结束   → 无表格结果</span></span>
<span class="line"><span>   └─ 出错     → 失败</span></span></code></pre></div><p>SQL Server PHP 驱动的 <code>sqlsrv_next_result()</code> 有三个不同返回值：<code>true</code> 表示成功切到下一结果，<code>null</code> 表示没有更多结果，<code>false</code> 表示切换出错。不能把后二者无条件混为一谈。<a href="https://learn.microsoft.com/en-us/sql/connect/php/sqlsrv-next-result?view=sql-server-ver17" target="_blank" rel="noreferrer">Microsoft 驱动说明</a></p><p>PDO 也有跨行集读取能力，但应依据对应驱动及错误模式处理失败，而不是直接套用另一驱动的返回值语义。<a href="https://www.php.net/manual/en/pdostatement.nextrowset.php" target="_blank" rel="noreferrer">PDOStatement::nextRowset</a></p><h2 id="第一个有列-是协议-需要明确取舍" tabindex="-1">“第一个有列”是协议，需要明确取舍 <a class="header-anchor" href="#第一个有列-是协议-需要明确取舍" aria-label="Permalink to &quot;“第一个有列”是协议，需要明确取舍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>执行结果</th><th>按当前约定应如何理解</th></tr></thead><tbody><tr><td>先出现受影响行数，再出现表格</td><td>跳过前者，读取表格</td></tr><tr><td>第一个表格有列但没有行</td><td>这是有效空结果，不应继续寻找非空表格</td></tr><tr><td>连续返回两张表格</td><td>只返回第一张，不能默认是最后一张</td></tr><tr><td>执行成功但没有任何表格</td><td>无表格结果，与执行失败不同</td></tr></tbody></table><p>因此，报表 SQL 中不应随手增加调试用的前置查询，否则它可能成为被展示的第一张表。需要多张结果表时，应扩展明确的返回协议，而不是依赖开发者猜测驱动行为。</p><h2 id="失败不能总被包装成空数组" tabindex="-1">失败不能总被包装成空数组 <a class="header-anchor" href="#失败不能总被包装成空数组" aria-label="Permalink to &quot;失败不能总被包装成空数组&quot;">​</a></h2><p>近期控制器开始把初始执行返回的 <code>false</code> 转成失败响应，避免把执行错误显示为“暂无数据”。这是有价值的进步，但还不是完整错误契约。</p><p>当前驱动适配仍有把结果集切换失败或捕获到的异常转为空数组的分支。因此文章不能宣称“所有数据库错误都已经正确上报”。建议继续把下面三种结果分开：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ReportOutcome</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">kind</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;table&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">columns</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">rows</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[][] }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">kind</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;no-table&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">kind</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;failure&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">incidentId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };</span></span></code></pre></div><p>这是建议的教学模型，并非当前接口。空表属于 <code>table</code>，它与无结果集、执行失败分别表达不同事实。</p><p>服务端内部错误可以用于排障，但对用户返回原始数据库错误可能暴露表名、结构或执行细节。建议在受控日志中保留原因，对外提供可关联的错误标识；日志本身也不要无差别记录完整参数与结果数据。</p><h2 id="支持-cte-不等于允许任意-sql" tabindex="-1">支持 CTE 不等于允许任意 SQL <a class="header-anchor" href="#支持-cte-不等于允许任意-sql" aria-label="Permalink to &quot;支持 CTE 不等于允许任意 SQL&quot;">​</a></h2><p>批处理读取能力只解决返回值问题，不会自动提供只读权限、租户隔离、超时限制或参数安全。前置语句仍可能有副作用，不能因最后返回了表格就把整段 SQL 当成只读查询。</p><p>对于允许维护报表 SQL 的系统，应独立核对：谁能修改语句、使用什么数据库权限、输入如何绑定、执行资源如何限制、审计如何脱敏。这些需要真实配置证据，不能靠此次兼容修复推出“已经安全”。</p><h2 id="页面每页更多-不等于服务端更快" tabindex="-1">页面每页更多，不等于服务端更快 <a class="header-anchor" href="#页面每页更多-不等于服务端更快" aria-label="Permalink to &quot;页面每页更多，不等于服务端更快&quot;">​</a></h2><p>配套前端近期还调大了报表默认每页条数。它改变用户一次看到多少行，却不改变上述封装一次读取整个首个结果集的事实。</p><p>因此要分别度量数据库执行、服务端取数、网络响应大小与浏览器渲染。数据规模增大时，可以评估服务端分页或游标，但不能把 UI 分页设置当作已经实现了这些能力。</p><h2 id="建议验证" tabindex="-1">建议验证 <a class="header-anchor" href="#建议验证" aria-label="Permalink to &quot;建议验证&quot;">​</a></h2><ul><li>[ ] 普通查询、前置注释和 CTE 都能返回预期列与行。</li><li>[ ] 声明、受影响行数之后的表格能够被正确读取。</li><li>[ ] 第一张空表不会被第二张非空表替代。</li><li>[ ] 语法错误、权限错误、超时及读取中断都不会误报成功空表。</li><li>[ ] 多驱动部署分别验证，不假定 PDO 与 SQLSRV 行为完全一样。</li><li>[ ] 大结果集检查内存、耗时和前端渲染，而不只看每页条数。</li></ul><p>延伸阅读：<a href="/practice/cross-client-api-contract">跨端 API 契约</a>、<a href="/backend/database">数据库与事务</a>。</p>`,31)])])}const g=a(e,[["render",l]]);export{o as __pageData,g as default};
